"""Original, schematic supply illustrations. These are not product photographs."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'assets'/'illustrations';OUT.mkdir(parents=True,exist_ok=True)
defs='''<defs><linearGradient id="bag" x1="0" x2="1"><stop stop-color="#dce7ec" stop-opacity=".6"/><stop offset=".35" stop-color="#fff" stop-opacity=".85"/><stop offset="1" stop-color="#c9dbe3" stop-opacity=".65"/></linearGradient><linearGradient id="blue" x1="0" x2="1"><stop stop-color="#107f9a"/><stop offset=".5" stop-color="#5eb7c9"/><stop offset="1" stop-color="#12647d"/></linearGradient><filter id="shadow"><feGaussianBlur stdDeviation="9"/></filter></defs>'''
def save(name,body,title):
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="800" height="580" viewBox="0 0 800 580" role="img" aria-labelledby="title"><title id="title">{title}</title>{defs}<rect width="800" height="580" fill="#f5f8fa"/>{body}</svg>'''
    (OUT/f'{name}.svg').write_text(svg,encoding='utf-8')
def bag(x,y,w,h,label):
    return f'''<g transform="translate({x} {y})"><ellipse cx="{w/2}" cy="{h+43}" rx="{w*.48}" ry="13" fill="#567080" opacity=".13" filter="url(#shadow)"/><path d="M20 0 H{w-20} Q{w} 0 {w} 22 V{h-20} Q{w} {h} {w-25} {h} H25 Q0 {h} 0 {h-20} V22 Q0 0 20 0Z" fill="url(#bag)" stroke="#9fb5c2" stroke-width="2"/><path d="M19 15 H{w-19} M13 29 V{h-30} M{w-13} 29 V{h-30} M20 {h-14} H{w-20}" fill="none" stroke="#fff" stroke-width="4" opacity=".8"/><rect x="{w/2-23}" y="11" width="46" height="12" rx="6" fill="#edf3f7" stroke="#a4bac7"/><path d="M15 {h*.55} Q{w*.5} {h*.52} {w-15} {h*.56} V{h-24} H15Z" fill="#b8d8e3" opacity=".22"/><rect x="{w*.17}" y="{h*.27}" width="{w*.66}" height="{h*.35}" rx="5" fill="#fff" stroke="#cedce5"/><path d="M{w*.25} {h*.35} H{w*.72} M{w*.25} {h*.4} H{w*.64} M{w*.25} {h*.45} H{w*.7}" stroke="#8dabb9" stroke-width="3"/><text x="{w*.25}" y="{h*.56}" fill="#173f5d" font-family="Arial,sans-serif" font-size="26" font-weight="600">{label}</text><g transform="translate({w*.35} {h})"><rect width="17" height="39" rx="5" fill="#d9e6eb" stroke="#91aab7"/><rect x="-4" y="28" width="25" height="25" rx="4" fill="url(#blue)"/><path d="M1 32 V49 M7 32 V49 M13 32 V49" stroke="#8bd1dd" stroke-width="2"/></g><g transform="translate({w*.64} {h})"><rect width="15" height="42" rx="4" fill="#e4ecef" stroke="#a0b5bf"/><rect x="-3" y="31" width="21" height="17" rx="3" fill="#eef3f5" stroke="#a8bdc7"/></g></g>'''
save('fluid-bags',bag(151,154,195,284,'2 L')+bag(413,80,244,358,'5 L'),'Technical illustration of two planned dialysis solution bag sizes')
